  font-weight: 600;
  line-height: 1.45;
}
.create-note .icon { width: 16px; height: 16px; margin-top: 1px; }
.create-footer {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 12px 20px calc(12px + var(--safe-b));
  border-top: 1px solid var(--line);
  background: rgba(245, 241, 233, .95);
  backdrop-filter: blur(14px);
}
.create-footer .btn-primary { width: 100%; }

/* ============ GAME HEADER ============ */
.game-screen { background: var(--paper); }
.game-header {
  flex: 0 0 auto;
  padding: calc(10px + var(--safe-t)) 14px 10px;
  background:
    radial-gradient(circle at 100% 0, rgba(20,184,166,.08), transparent 45%),
    rgba(245, 241, 233, .96);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(14px);
  z-index: 5;
}
.identity-row {
  display: flex;
  align-items: center;
  gap: 9px;
}
.avatar-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 2px solid rgba(255,255,255,.9);
  border-radius: 15px;
  background: linear-gradient(145deg, var(--teal-soft), #f8e9c8);
  box-shadow: 0 5px 14px rgba(30,38,55,.12);
  font-size: 25px;
  cursor: pointer;
  flex: 0 0 auto;
}
.avatar-dot {
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 12px;
  height: 12px;
  border: 2.5px solid var(--paper);
  border-radius: 50%;
  background: var(--green);
  display: none;
}
.avatar-dot.is-alive { display: block; }
.identity { flex: 1; min-width: 0; }
.identity-name {
  font-size: 16px;
  font-weight: 850;
  letter-spacing: -.035em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}
.identity-meta {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: .01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.money-pill {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  min-width: 70px;
  height: 42px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
  color: var(--ink);
  cursor: pointer;
  flex: 0 0 auto;
  box-shadow: var(--shadow-sm);
}
.money-pill span {
  font-size: 13.5px;
  font-weight: 850;
  letter-spacing: -.02em;
  line-height: 1.15;
  white-space: nowrap;
}
.money-pill span.is-negative { color: var(--red); }
.money-pill small {
  font-size: 8px;
  color: var(--muted-2);
  font-weight: 750;
  line-height: 1.2;
  white-space: nowrap;
}
.header-settings {
  width: 38px;
  height: 38px;
  background: var(--card);
  border: 1px solid var(--line);
  color: var(--muted);
  box-shadow: var(--shadow-sm);
}
.header-settings .icon { width: 18px; height: 18px; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-top: 9px;
}
.stat {
  position: relative;
  min-width: 0;
  padding: 6px 7px 7px;
  border-radius: 11px;
  background: var(--card);
  border: 1px solid var(--line);
  overflow: hidden;
}
.stat-top {
  display: flex;
  align-items: center;
  gap: 3px;
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: .02em;
  text-transform: uppercase;
  white-space: nowrap;
}
.stat-top .emoji { font-size: 11px; line-height: 1; }
.stat-top b {
  margin-left: auto;
  color: var(--ink);
  font-size: 10.5px;
  letter-spacing: -.02em;
}
.stat-bar {
  height: 3px;
  margin-top: 5px;
  border-radius: 99px;
  background: var(--paper-2);
  overflow: hidden;
}
.stat-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  transition: width .45s cubic-bezier(.2,.8,.2,1);
}
.stat[data-stat="happiness"] .stat-bar i { background: var(--gold); }
.stat[data-stat="health"] .stat-bar i { background: var(--green); }
.stat[data-stat="smarts"] .stat-bar i { background: var(--blue); }
.stat[data-stat="looks"] .stat-bar i { background: var(--purple); }
.stat.is-low .stat-top b { color: var(--red); }

/* ============ GAME BODY ============ */
.screen-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 12px;
}
.panel { padding: 15px 14px 4px; }
.panel-intro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 13px;
}
.panel-title {
  margin: 0;
  font-size: 21px;
  letter-spacing: -.045em;
  font-weight: 900;
  line-height: 1.08;
}
.panel-sub {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.4;
  font-weight: 550;
}
.year-chip {
  flex: 0 0 auto;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--card);
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.section-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 18px 2px 9px;
}
.section-head h3 {
  margin: 0;
  font-size: 11px;
  letter-spacing: .13em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 850;
}
.section-head .icon { width: 14px; height: 14px; color: var(--coral); }
.section-head .spacer { flex: 1; }
.section-head small { color: var(--muted-2); font-size: 10px; font-weight: 650; }

/* Timeline */
.timeline { padding: 14px 14px 8px; }
.tl-item {
  display: grid;
  grid-template-columns: 36px 1fr;
  gap: 9px;
  position: relative;
  animation: tlIn .36s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes tlIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.tl-item + .tl-item { margin-top: 10px; }
.tl-rail { position: relative; display: flex; flex-direction: column; align-items: center; }
.tl-item:not(:last-child) .tl-rail::after {
  content: "";
  position: absolute;
  top: 29px;
  bottom: -20px;
  width: 2px;
  border-radius: 2px;
  background: var(--line);
}
.tl-age {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  margin-top: 3px;
  border-radius: 9px;
  background: var(--paper-2);
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: -.02em;
  z-index: 1;
}
.tl-card {
  position: relative;
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--card);
  box-shadow: 0 2px 8px rgba(30,38,55,.035);
}
.tl-card::before {
  content: "";
  position: absolute;
  left: -5px;
  top: 12px;
  width: 9px;
  height: 9px;
  border-left: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--card);
  transform: rotate(45deg);
  border-radius: 0 0 0 2px;
}
.tl-item[data-type="birth"] .tl-age { background: var(--coral-soft); border-color: #ffd3cc; color: var(--coral-dark); }
.tl-item[data-type="birth"] .tl-card { border-color: #ffd8d1; background: linear-gradient(145deg, #fffdf8, #fff4f1); }
.tl-item[data-type="milestone"] .tl-age { background: var(--gold-soft); border-color: #f6dfa3; color: #9a6a06; }
.tl-item[data-type="love"] .tl-age { background: #ffe5e9; border-color: #ffccd4; color: #c33850; }
.tl-item[data-type="money"] .tl-age { background: var(--green-soft); border-color: #bce8d3; color: var(--teal-dark); }
.tl-item[data-type="bad"] .tl-age { background: var(--red-soft); border-color: #ffc9c9; color: #b13737; }
.tl-item[data-type="career"] .tl-age { background: var(--blue-soft); border-color: #c8d9fb; color: #2f61bd; }
.tl-item[data-type="health"] .tl-age { background: var(--teal-soft); border-color: #b8eae2; color: var(--teal-dark); }
.tl-head {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 3px;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .11em;
  text-transform: uppercase;
  color: var(--muted-2);
}
.tl-head .icon { width: 12px; height: 12px; color: var(--coral); }
.tl-item[data-type="money"] .tl-head .icon { color: var(--green); }
.tl-item[data-type="career"] .tl-head .icon { color: var(--blue); }
.tl-item[data-type="love"] .tl-head .icon { color: #d94c67; }
.tl-item[data-type="bad"] .tl-head .icon { color: var(--red); }
.tl-text {
  color: var(--ink-2);
  font-size: 12.8px;
  font-weight: 550;
  line-height: 1.5;
  letter-spacing: -.005em;
}
.tl-text strong { font-weight: 800; color: var(--ink); }
.tl-effects {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}
.effect {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px 6px;
  border-radius: 6px;
  background: var(--paper);
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .01em;
}
.effect.pos { background: var(--green-soft); color: #177a51; }
.effect.neg { background: var(--red-soft); color: #ad3b3b; }
.effect.money { background: var(--gold-soft); color: #8b5c05; }

.timeline-end {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: center;
  padding: 18px 0 6px;
  color: var(--muted-2);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: .02em;
}
.timeline-end .line { width: 24px; height: 1px; background: var(--line-strong); }

/* Cards / lists */
.stack { display: flex; flex-direction: column; gap: 8px; }
.card {
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
  box-shadow: 0 2px 8px rgba(30,38,55,.035);
}
.action-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--card);
  box-shadow: 0 2px 8px rgba(30,38,55,.035);
  transition: border-color .15s ease, opacity .15s ease;
}
.action-card.is-used { opacity: .55; }
.action-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: var(--paper);
  font-size: 21px;
  flex: 0 0 auto;
}
.action-icon.tint-teal { background: var(--teal-soft); }
.action-icon.tint-coral { background: var(--coral-soft); }
.action-icon.tint-gold { background: var(--gold-soft); }
.action-icon.tint-purple { background: var(--purple-soft); }
.action-icon.tint-blue { background: var(--blue-soft); }
.action-main { flex: 1; min-width: 0; }
.action-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13.5px;
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.2;
}
.action-desc {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.35;
  font-weight: 550;
}
.action-meta {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 5px;
}
.action-cost {
  color: var(--ink);
  font-size: 9.5px;
  font-weight: 800;
  padding: 2px 5px;
  border-radius: 5px;
  background: var(--paper);
}
.action-btn {
  flex: 0 0 auto;
  min-width: 54px;
  height: 34px;
  padding: 0 11px;
  border: 0;
  border-radius: 10px;
  background: var(--ink);
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .02em;
  cursor: pointer;
  transition: transform .12s ease, opacity .15s ease;
}
.action-btn:active { transform: scale(.95); }
.action-btn.alt { background: var(--teal); }
.action-btn.gold { background: var(--gold); color: #4d3200; }
.action-btn:disabled { opacity: .35; pointer-events: none; }
.action-btn.is-done { background: var(--paper-2); color: var(--muted); }

.money-hero {
  position: relative;
  padding: 16px;
  border-radius: 19px;
  background:
    radial-gradient(circle at 100% 0, rgba(255,255,255,.15), transparent 42%),
    linear-gradient(145deg, #1a2638, #111927);
  color: #fff;
  overflow: hidden;
  box-shadow: 0 12px 28px rgba(17,25,39,.2);
}
.money-hero::after {
  content: "$";
  position: absolute;
  right: -4px;
  bottom: -28px;
  font-size: 118px;
  font-weight: 900;
  color: rgba(255,255,255,.045);
  line-height: 1;
}
.money-label {
  display: flex;
  align-items: center;
  gap: 5px;
  color: rgba(255,255,255,.5);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.money-label .icon { width: 13px; height: 13px; }
.money-value {
  margin-top: 4px;
  font-size: 33px;
  line-height: 1;
  letter-spacing: -.055em;
  font-weight: 900;
}
.money-value.negative { color: #ff9f9f; }
.money-sub {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid rgba(255,255,255,.1);
  color: rgba(255,255,255,.66);
  font-size: 9.5px;
  font-weight: 650;
}
.money-sub b { display: block; margin-top: 1px; color: #fff; font-size: 12px; letter-spacing: -.02em; }
.money-sub .pos { color: #75e4bc; }
.money-sub .neg { color: #ff9d9d; }

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-top: 9px;
}
.kpi {
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
}
.kpi-label { color: var(--muted-2); font-size: 8px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.kpi-value { margin-top: 2px; font-size: 15px; font-weight: 850; letter-spacing: -.04em; }

.progress-block { margin-top: 9px; }
.progress-label {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 750;
}
.progress-label b { color: var(--ink); }
.progress {
  height: 6px;
  border-radius: 99px;
  background: var(--paper-2);
  overflow: hidden;
}
.progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--teal), #48d6c0);
  transition: width .4s ease;
}
.progress.coral i { background: linear-gradient(90deg, var(--coral), #ff9a72); }
.progress.blue i { background: linear-gradient(90deg, var(--blue), #83b1ff); }

.person-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--card);
  cursor: pointer;
  text-align: left;
  width: 100%;
  box-shadow: 0 2px 8px rgba(30,38,55,.035);
}
.person-card:active { background: #faf7f0; }
.person-avatar {
  position: relative;
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  border-radius: 13px;
  background: var(--paper);
  font-size: 24px;
  flex: 0 0 auto;
}
.person-avatar.dead { filter: grayscale(1); opacity: .65; }
.person-avatar .tiny-heart {
  position: absolute;
  right: -3px;
  bottom: -3px;
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  border: 2px solid var(--card);
  border-radius: 50%;
  background: #ffd4dc;
  font-size: 8px;
}
.person-info { flex: 1; min-width: 0; }
.person-name {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.person-role {
  margin-top: 1px;
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 650;
}
.person-rel {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 5px;
}
.person-rel .progress { flex: 1; height: 4px; }
.person-rel b { color: var(--muted); font-size: 8.5px; min-width: 22px; text-align: right; }
.person-chevron { color: var(--muted-2); }
.person-chevron .icon { width: 16px; height: 16px; }

.partner-card {
  position: relative;
  padding: 14px;
  border-radius: 17px;
  background: linear-gradient(145deg, #fff0f1, #fff8f3);
  border: 1px solid #ffd7d8;
  overflow: hidden;
}
.partner-card::after {
  content: "♥";
  position: absolute;
  right: 10px;
  top: -8px;
  color: rgba(228,88,88,.09);
  font-size: 78px;
  line-height: 1;
}
.partner-row { display: flex; align-items: center; gap: 10px; position: relative; z-index: 1; }
.partner-avatar {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 15px;
  background: #fff;
  font-size: 27px;
  box-shadow: 0 4px 12px rgba(196,74,83,.1);
}
.partner-name { font-size: 15px; font-weight: 850; letter-spacing: -.03em; }
.partner-meta { margin-top: 2px; color: #a76a6a; font-size: 10px; font-weight: 650; }
.partner-actions { display: flex; gap: 6px; margin-top: 10px; position: relative; z-index: 1; flex-wrap: wrap; }
.partner-actions .action-btn { height: 32px; min-width: 0; flex: 1; }

.empty-card {
  padding: 18px;
  border: 1px dashed var(--line-strong);
  border-radius: 16px;
  background: rgba(255,255,255,.45);
  text-align: center;
}
.empty-icon { font-size: 31px; }
.empty-title { margin-top: 5px; font-size: 14px; font-weight: 850; letter-spacing: -.02em; }
.empty-text { margin: 3px auto 0; max-width: 250px; color: var(--muted); font-size: 10.5px; line-height: 1.45; }
.empty-card .btn { margin-top: 11px; min-height: 38px; font-size: 11px; padding: 0 16px; }

.asset-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.asset-card {
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--card);
  box-shadow: 0 2px 8px rgba(30,38,55,.035);
}
.asset-icon { font-size: 23px; }
.asset-name { margin-top: 5px; font-size: 11.5px; font-weight: 800; letter-spacing: -.02em; line-height: 1.2; }
.asset-value { margin-top: 2px; color: var(--muted); font-size: 9.5px; font-weight: 650; }
.asset-card .action-btn { width: 100%; margin-top: 8px; height: 29px; font-size: 9px; }

.job-hero {
  padding: 14px;
  border-radius: 17px;
  background:
    radial-gradient(circle at 100% 0, rgba(20,184,166,.16), transparent 45%),
    var(--card);
  border: 1px solid var(--line);
}
.job-head { display: flex; align-items: flex-start; gap: 10px; }
.job-logo {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 13px;
  background: var(--teal-soft);
  font-size: 24px;
  flex: 0 0 auto;
}
.job-title { font-size: 15px; font-weight: 850; letter-spacing: -.03em; line-height: 1.2; }
.job-company { margin-top: 2px; color: var(--muted); font-size: 10px; font-weight: 600; }
.job-pay { margin-left: auto; text-align: right; }
.job-pay b { display: block; font-size: 15px; font-weight: 850; letter-spacing: -.03em; }
.job-pay small { color: var(--muted-2); font-size: 8px; font-weight: 750; }
.job-actions { display: flex; gap: 6px; margin-top: 10px; }
.job-actions .action-btn { flex: 1; min-width: 0; }
.job-actions .action-btn.danger { background: var(--red-soft); color: #b33d3d; }

.job-listing {
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--card);
}
.job-listing-top { display: flex; align-items: center; gap: 9px; }
.job-listing .job-logo { width: 35px; height: 35px; border-radius: 10px; font-size: 19px; background: var(--paper); }
.job-listing .job-title { font-size: 12px; }
.job-listing .job-company { font-size: 9px; }
